// GroundedKit Cloudflare Pages "advanced mode" worker. Dependency-free.
//  - /api/waitlist : waitlist form (KV binding WAITLIST)
//  - /mcp          : free, read-only remote MCP server (Streamable HTTP, JSON-RPC 2.0, stateless, JSON responses)
//  - everything else falls through to static assets (env.ASSETS.fetch); _routes.json limits which paths reach this file.
// build.py injects the claims data at the CLAIMS marker below; edit this file in site/worker/, not in dist/.

// ---------- waitlist ----------
// Stores: key = lowercased email, value = {"joined": ISO timestamp, "source": "site"}. No IP, no other data.
const EMAIL_RE = /^[^\s@<>"]{1,64}@[^\s@<>"]{1,190}\.[a-z]{2,24}$/i;
const CONTACT = "hello@groundedkit.com";

function wantsJson(req) {
  return (req.headers.get("accept") || "").includes("application/json");
}
function reply(req, ok, msg, status) {
  if (wantsJson(req)) {
    return new Response(JSON.stringify({ ok, message: msg }), {
      status, headers: { "content-type": "application/json; charset=utf-8" } });
  }
  if (ok) return Response.redirect(new URL("/thanks/", req.url).toString(), 303);
  const html = `<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex">
<meta name="viewport" content="width=device-width, initial-scale=1"><title>Waitlist | GroundedKit</title>
<link rel="stylesheet" href="/styles.css"></head><body><main class="wrap"><h1>Something went wrong</h1>
<p>${msg}</p><p>You can also join by emailing <a href="mailto:${CONTACT}?subject=Waitlist">${CONTACT}</a>.</p>
<p><a href="/">Back to GroundedKit</a></p></main></body></html>`;
  return new Response(html, { status, headers: { "content-type": "text/html; charset=utf-8" } });
}

async function handleWaitlist(req, env) {
  if (req.method !== "POST") return reply(req, false, "Use the form on the home page.", 405);
  let email = "", trap = "";
  const ct = req.headers.get("content-type") || "";
  try {
    if (ct.includes("application/json")) {
      const b = await req.json(); email = String(b.email || ""); trap = String(b.company_url || "");
    } else {
      const f = await req.formData(); email = String(f.get("email") || ""); trap = String(f.get("company_url") || "");
    }
  } catch { return reply(req, false, "We couldn't read that form submission.", 400); }
  if (trap) return reply(req, true, "ok", 200); // honeypot: pretend success, store nothing
  email = email.trim().toLowerCase();
  if (email.length > 254 || !EMAIL_RE.test(email)) return reply(req, false, "That email address doesn't look valid.", 400);
  if (!env.WAITLIST) return reply(req, false, "The waitlist isn't connected yet.", 503);
  const existing = await env.WAITLIST.get(email);
  if (!existing) await env.WAITLIST.put(email, JSON.stringify({ joined: new Date().toISOString(), source: "site" }));
  return reply(req, true, "You're on the list.", 200);
}

