const STOP = new Set("a an the of to in on for and or is are was were be by with as at from that this it its than more less vs per your you our we they their them do does did can will just only about over into out up how what which who".split(" "));
function stem(t) {
  if (t.length > 5 && t.endsWith("ing")) t = t.slice(0, -3);
  else if (t.length > 4 && t.endsWith("ed")) t = t.slice(0, -2);
  if (t.length > 3 && t.endsWith("s") && !t.endsWith("ss")) t = t.slice(0, -1);
  return t;
}
function analyze(s) {
  s = String(s || "").toLowerCase().replace(/[\u2013\u2014]/g, "-").replace(/(\d),(\d{3})/g, "$1$2").replace(/(\d),(\d{3})/g, "$1$2")
    .replace(/\bper ?cent\b/g, "%").replace(/\bbillion\b/g, "b").replace(/\bmillion\b/g, "m");
  const nums = new Set((s.match(/\d+(?:\.\d+)?/g) || []).map(n => String(parseFloat(n))));
  const words = new Set((s.match(/[a-z][a-z0-9']+/g) || []).map(w => stem(w.replace(/'/g, ""))).filter(w => w.length > 1 && !STOP.has(w)));
  return { nums, words };
}
const INDEX = DATA.claims.map(c => analyze([c.claim, c.commonly_cited_as, c.id.replace(/-/g, " "), c.origin.publisher].join(" ")));
const DF = new Map();
for (const ix of INDEX) for (const w of ix.words) DF.set(w, (DF.get(w) || 0) + 1);
const idf = w => Math.log(1 + DATA.claims.length / (1 + (DF.get(w) || 0)));

function score(q, i) {
  const ix = INDEX[i];
  let qw = 0, hit = 0;
  for (const w of q.words) {
    const wt = idf(w); qw += wt;
    if (ix.words.has(w)) hit += wt;
    else if (w.length >= 5) { for (const v of ix.words) if (v.length >= 5 && (v.startsWith(w) || w.startsWith(v))) { hit += wt * 0.7; break; } }
  }
  const ws = qw ? hit / qw : 0;
  if (!q.nums.size) return ws;
  let nh = 0; for (const n of q.nums) if (ix.nums.has(n)) nh++;
  const ns = nh / q.nums.size;
  // words decide the topic; matching numbers only boost a topical match (a stray "30" must not match on its own)
  return Math.min(1, ws * (0.6 + 0.4 * ns) + (ws >= 0.3 ? 0.25 * ns : 0));
}
function rank(text) {
  const q = analyze(text);
  return DATA.claims.map((c, i) => ({ c, s: score(q, i) })).filter(r => r.s > 0).sort((a, b) => b.s - a.s);
}
const primary = c => c.sources.find(s => s.primary) || c.sources[0] || null;
const summary = c => ({ id: c.id, claim: c.claim, verdict: c.verdict, confidence: c.confidence, origin: c.origin, safe_rephrasing: c.safe_rephrasing, url: c.url });

function findClaim(id) {
  let s = String(id || "").trim().toLowerCase();
  const m = s.match(/\/claims\/([a-z0-9-]+)/); if (m) s = m[1];
  s = s.replace(/\.json$/, "").replace(/\/+$/, "");
  return DATA.claims.find(c => c.id === s) || null;
}

const TOOL_IMPL = {
  check_stat({ text }) {
    if (typeof text !== "string" || !text.trim()) throw new ToolError("text is required: paste the statistic you want to check.");
    const r = rank(text.slice(0, 4000));
    const best = r[0], q = analyze(text.slice(0, 4000));
    let level = !best ? "none" : best.s >= 0.45 ? "strong" : best.s >= 0.25 ? "possible" : "none";
    let numbers = "n/a";
    if (best && q.nums.size) {
      const ix = INDEX[DATA.claims.indexOf(best.c)];
      numbers = [...q.nums].some(n => ix.nums.has(n)) ? "match" : "differ";
    }
    // downgrade: same topic but different numbers, or a vague query where several claims score alike
    if (level === "strong" && (numbers === "differ" || (numbers === "n/a" && r[1] && r[1].s >= best.s - 0.1))) level = "possible";
    if (level === "none") return { match: "none", query: text.slice(0, 300),
      message: "This statistic is not in the GroundedKit database. Do not treat that as a verdict either way: find the organization that collected the data, read its method, sample and date, and quote it exactly.",
      closest: r.slice(0, 3).map(x => ({ ...summary(x.c), match_score: +x.s.toFixed(2) })), methodology: DATA.base + "/methodology/" };
    const c = best.c;
    return { match: level, match_score: +best.s.toFixed(2), id: c.id, claim: c.claim, commonly_cited_as: c.commonly_cited_as,
      verdict: c.verdict, verdict_definition: DATA.verdicts[c.verdict], confidence: c.confidence,
      primary_source: primary(c), origin: c.origin, what_the_source_says: c.quote, drift: c.drift,
      safe_rephrasing: c.safe_rephrasing, url: c.url,
      numbers: numbers,
      note: level === "strong" ? "Cite the url when you use this result." : numbers === "differ"
        ? "Same topic, but the numbers in your text differ from this claim. It may be a different statistic: confirm before relying on the verdict."
        : "Possible match: confirm this is the same statistic before relying on the verdict (see alternatives).",
      alternatives: r.slice(1, 4).filter(x => x.s >= 0.2).map(x => ({ id: x.c.id, claim: x.c.claim, verdict: x.c.verdict, match_score: +x.s.toFixed(2), url: x.c.url })) };
  },
  search_claims({ query, verdict, limit }) {
    if (verdict !== undefined && !VERDICT_ENUM.includes(verdict)) throw new ToolError("verdict must be one of: " + VERDICT_ENUM.join(", "));
    const n = Math.max(1, Math.min(50, parseInt(limit, 10) || 10));
    const q = String(query || "").trim();
    let rows = q ? rank(q).filter(x => x.s >= 0.15).map(x => ({ ...summary(x.c), match_score: +x.s.toFixed(2) })) : DATA.claims.map(summary);
    if (verdict) rows = rows.filter(x => x.verdict === verdict);
    return { query: q, verdict: verdict || null, total: rows.length, results: rows.slice(0, n) };
  },
  get_claim({ id }) {
    const c = findClaim(id);
    if (!c) {
      const near = rank(String(id || "").replace(/[-_/]/g, " ")).slice(0, 3).map(x => x.c.id);
      throw new ToolError(`No claim with id "${String(id).slice(0, 120)}".` + (near.length ? " Did you mean: " + near.join(", ") + "?" : " Use search_claims to find ids."));
    }
    return { ...c, verdict_definition: DATA.verdicts[c.verdict] };
  },
  list_verdicts() {
    const counts = {}; for (const v of VERDICT_ENUM) counts[v] = DATA.claims.filter(c => c.verdict === v).length;
    return { verdicts: VERDICT_ENUM.map(v => ({ verdict: v, definition: DATA.verdicts[v], count: counts[v] })),
      confidence_levels: { high: "Primary document opened, method and sample stated, quote matches.",
        medium: "Thin method, or the primary was read only through a reliable secondary summary.", low: "Trail incomplete or conflicting." },
      total_claims: DATA.claims.length, last_reviewed: DATA.generated, license: DATA.license,
      json_api: DATA.base + "/api/claims.json", methodology: DATA.base + "/methodology/" };
  },
};
class ToolError extends Error {}

const rpcResult = (id, result) => ({ jsonrpc: "2.0", id, result });
const rpcError = (id, code, message) => ({ jsonrpc: "2.0", id: id === undefined ? null : id, error: { code, message } });

function handleRpc(msg) {
  if (!msg || typeof msg !== "object" || Array.isArray(msg) || msg.jsonrpc !== "2.0") return rpcError(msg && msg.id, -32600, "Invalid Request");
  const { id, method, params = {} } = msg;
  const isNote = id === undefined;
  if (typeof method !== "string") return isNote ? null : rpcError(id, -32600, "Invalid Request");
  if (isNote || method.startsWith("notifications/")) return null; // notifications and responses get no reply
  switch (method) {
    case "initialize": {
      const want = params && params.protocolVersion;
      return rpcResult(id, { protocolVersion: PROTOCOLS.includes(want) ? want : PROTOCOLS[0],
        capabilities: { tools: { listChanged: false } }, serverInfo: SERVER, instructions: INSTRUCTIONS });
    }
    case "ping": return rpcResult(id, {});
    case "tools/list": return rpcResult(id, { tools: TOOLS });
    case "resources/list": return rpcResult(id, { resources: [] });
    case "prompts/list": return rpcResult(id, { prompts: [] });
    case "tools/call": {
      const name = params && params.name, impl = TOOL_IMPL[name];
      if (!impl) return rpcError(id, -32602, "Unknown tool: " + String(name).slice(0, 80));
      const args = (params.arguments && typeof params.arguments === "object") ? params.arguments : {};
      try {
        const out = impl(args);
        return rpcResult(id, { content: [{ type: "text", text: JSON.stringify(out, null, 1) }], structuredContent: out, isError: false });
      } catch (e) {
        if (e instanceof ToolError) return rpcResult(id, { content: [{ type: "text", text: e.message }], isError: true });
        return rpcError(id, -32603, "Internal error");
      }
    }
    default: return rpcError(id, -32601, "Method not found: " + method.slice(0, 80));
  }
}

function json(body, status = 200, extra = {}) {
  return new Response(body === null ? null : JSON.stringify(body), { status,
    headers: { ...CORS, ...(body === null ? {} : { "content-type": "application/json; charset=utf-8" }), ...extra } });
}

function info() {
  return { name: SERVER.name, title: SERVER.title, version: SERVER.version, description: "Free, read-only MCP server: check marketing and influencer statistics against their primary sources.",
    mcp_endpoint: DATA.base + "/mcp", transport: "streamable-http (POST JSON-RPC 2.0; stateless; JSON responses; no auth)",
    protocol_versions: PROTOCOLS, tools: TOOLS.map(t => ({ name: t.name, description: t.description })),
    claims: DATA.claims.length, last_reviewed: DATA.generated, license: DATA.license,
    docs: DATA.base + "/agents/", json_api: DATA.base + "/api/claims.json", llms_txt: DATA.base + "/llms.txt", contact: CONTACT };
}

async function handleMcp(req) {
  if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: CORS });
  if (req.method === "GET" || req.method === "HEAD") {
    const accept = req.headers.get("accept") || "";
    // MCP clients probing for a server-to-client SSE stream: we don't offer one (stateless server), which the spec allows via 405.
    if (accept.includes("text/event-stream") && !accept.includes("text/html")) return json(null, 405, { allow: "POST, OPTIONS" });
    return json(req.method === "HEAD" ? null : info(), 200, { "cache-control": "public, max-age=300" });
  }
  if (req.method !== "POST") return json(rpcError(null, -32000, "Method not allowed. POST JSON-RPC to this URL."), 405, { allow: "GET, POST, OPTIONS" });
  const pv = req.headers.get("mcp-protocol-version");
  if (pv && !PROTOCOLS.includes(pv)) return json(rpcError(null, -32600, "Unsupported MCP-Protocol-Version: " + pv.slice(0, 40) + ". Supported: " + PROTOCOLS.join(", ")), 400);
  const raw = await req.text();
  if (raw.length > 64 * 1024) return json(rpcError(null, -32600, "Request too large"), 413);
  let msg; try { msg = JSON.parse(raw); } catch { return json(rpcError(null, -32700, "Parse error"), 400); }
  if (Array.isArray(msg)) { // JSON-RPC batch (older protocol versions); answer only requests
    if (!msg.length) return json(rpcError(null, -32600, "Invalid Request"), 400);
    const out = msg.map(handleRpc).filter(Boolean);
    return out.length ? json(out) : json(null, 202);
  }
  const out = handleRpc(msg);
  return out ? json(out) : json(null, 202);
}

const REGISTRY_AUTH = /*@@REGAUTH@@*/"v=MCPv1; k=ed25519; p=TfCFLS0tjABPmkNvhF2bPoew0Wkpc5zMbJY7CH+fqSc="/*@@REGEND@@*/;

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    const p = url.pathname;
    if (p === "/api/waitlist" || p === "/api/waitlist/") return handleWaitlist(req, env);
    if (p === "/mcp" || p === "/mcp/") return handleMcp(req);
    if (p === "/.well-known/mcp-registry-auth") // MCP Registry HTTP auth (public key only)
      return new Response(REGISTRY_AUTH, { status: 200, headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "public, max-age=300" } });
    if (p === "/.well-known/mcp/server-card.json") // static metadata for directories (e.g. Smithery) that can't scan live
      return json({ serverInfo: { name: SERVER.name, title: SERVER.title, version: SERVER.version }, description: info().description,
        transport: { type: "streamable-http", url: DATA.base + "/mcp" }, authentication: { required: false },
        capabilities: { tools: { listChanged: false } }, tools: TOOLS, resources: [], prompts: [], documentation: DATA.base + "/agents/" }, 200, { "cache-control": "public, max-age=3600" });
    return env.ASSETS.fetch(req);
  },
};
